// `amount` is `total.closing_balance.value` and `currency_code` is that
// object's `currency_code`. This is the balance at the end of `period_to`,
// not an amount available to withdraw — the Seller API does not return one.
// When the amount is RUB and the store contract currency is not, `fx_*`
// carries the Bank of Russia quote used for display (`amount / fx_rate`).
type WorkspaceStoreFinanceBalance struct {
	// Amount Decimal text of the period-end amount, two fraction digits.
	Amount *string `json:"amount,omitempty"`

	// CurrencyCode ISO code from `total.closing_balance.currency_code`.
	CurrencyCode *string `json:"currency_code,omitempty"`
	FetchedAtMs  int64   `json:"fetched_at_ms"`

	// FxAsOf Calendar day of `fx_rate`, `YYYY-MM-DD`.
	FxAsOf *string `json:"fx_as_of,omitempty"`

	// FxQuote Contract currency the RUB amount converts toward. Present only when
	// the reported currency is RUB, the contract currency is not, and a
	// central-bank quote was stamped.
	FxQuote *string `json:"fx_quote,omitempty"`

	// FxRate Rubles per one unit of `fx_quote`.
	FxRate *string `json:"fx_rate,omitempty"`

	// FxSource Quote source. Display conversion accepts only `cbr`.
	FxSource *string `json:"fx_source,omitempty"`

	// Outcome What the last `POST /v1/finance/balance` attempt produced.
	Outcome WorkspaceStoreFinanceBalanceOutcome `json:"outcome"`

	// PeriodTo `date_to` of the report, `YYYY-MM-DD` (Moscow calendar, closed day).
	PeriodTo string `json:"period_to"`
}

// WorkspaceStoreFinanceBalanceOutcome What the last `POST /v1/finance/balance` attempt produced.
type WorkspaceStoreFinanceBalanceOutcome string

