// WorkspaceStorePermissions Effective permissions for the authenticated actor on one Store.
type WorkspaceStorePermissions struct {
	DeleteStore bool `json:"delete_store"`
	EditName    bool `json:"edit_name"`

	// ManageKey Register, rotate, or clear the hosted key.
	ManageKey bool `json:"manage_key"`

	// ManageKeyGrants Owner, and only when the Store currently has an Assignee.
	ManageKeyGrants bool `json:"manage_key_grants"`
	ManageStore     bool `json:"manage_store"`
	ManageTags      bool `json:"manage_tags"`

	// TestKey Visible, live, and Cloud already holds ciphertext. Not a key-write grant.
	TestKey bool `json:"test_key"`
}

// WorkspaceStoreProductQuota Last successful Seller product-quota snapshot for this Store.
//
// This is Ozon's cabinet quota, not the Workspace store-seat quota. Absent until
// a hosted-key read succeeds.
type WorkspaceStoreProductQuota struct {
	DailyCreate *WorkspaceStoreProductQuotaBucket `json:"daily_create,omitempty"`
	DailyUpdate *WorkspaceStoreProductQuotaBucket `json:"daily_update,omitempty"`
	FetchedAtMs int64                             `json:"fetched_at_ms"`
	Total       *WorkspaceStoreProductQuotaTotal  `json:"total,omitempty"`
}

// WorkspaceStoreProductQuotaBucket One Ozon product-upload bucket from `/v4/product/info/limit`.
//
// `limit == -1` means Ozon does not cap this bucket. Remaining capacity is
// `max(0, limit - usage)` when `limit >= 0`.
type WorkspaceStoreProductQuotaBucket struct {
	Limit int64 `json:"limit"`
	Usage int64 `json:"usage"`
}

// WorkspaceStoreProductQuotaCategory Additional upload quota for one in-demand category
// (`total.quota_by_category` in `/v4/product/info/limit`).
//
// Products in the category consume this quota before the basic `total` bucket.
type WorkspaceStoreProductQuotaCategory struct {
	// CategoryId Ozon description-category id.
	CategoryId int64 `json:"category_id"`
	Limit      int64 `json:"limit"`
	Usage      int64 `json:"usage"`
}

// WorkspaceStoreProductQuotaTotal Basic product-upload limit plus the additional in-demand-category quotas.
type WorkspaceStoreProductQuotaTotal struct {
	// Archived Archived products at snapshot time (`/v3/product/list` ARCHIVED total).
	// Each archived product refunds +1 to the limit in the cabinet's
	// accounting, so the effective limit is `limit + archived`. Absent when
	// the archived count could not be read.
	Archived *int64 `json:"archived,omitempty"`

	// Categories Per-category additional quotas. Empty when the cabinet has none.
	Categories *[]WorkspaceStoreProductQuotaCategory `json:"categories,omitempty"`

	// Limit Base limit from `/v4/product/info/limit` (archive refunds excluded).
	Limit int64 `json:"limit"`

	// Usage Products counting against the limit, archived included.
	Usage int64 `json:"usage"`
}

